{"path": "dominoes.py", "content": "def can_chain(dominoes):
    """Return a list of stones forming a closed domino chain, or None."""
    stones = [tuple(stone) for stone in dominoes]
    if not stones:
        return []

    used = [False] * len(stones)
    chain = []

    def search(end):
        if len(chain) == len(stones):
            return chain[0][0] == chain[-1][1]
        tried = set()
        for index, (left, right) in enumerate(stones):
            if used[index]:
                continue
            if left == end:
                oriented = (left, right)
            elif right == end:
                oriented = (right, left)
            else:
                continue
            if oriented in tried:
                continue
            tried.add(oriented)
            used[index] = True
            chain.append(oriented)
            if search(oriented[1]):
                return True
            chain.pop()
            used[index] = False
        return False

    first = stones[0]
    used[0] = True
    chain.append(first)
    if search(first[1]):
        return list(chain)
    return None
